async function authorize(){try{gate.textContent='Validating authorization and establishing assessment…';const d=await jf('/api/assessment/authorize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({targetUrl:target.value,authorized:auth.checked})});assessmentId=d.assessmentId;targetOrigin=d.targetOrigin;sessionToken=d.sessionToken;gate.textContent='AUTHORIZED · '+assessmentId+' · '+targetOrigin+' · full URL analysis starting';state.textContent='AUTHORIZED';loadDocs();await loadSecurityWorkspace();await loadSecurityAssets();tool.value='all';await scan()}catch(e){gate.textContent=e.message;state.textContent='FAILED'}}
async function quickScan(){if(!assessmentId)return;try{raw.textContent='Running live HTTP posture probe…';const d=await jf('/api/scans/quick',{method:'POST',headers:{'Content-Type':'application/json','x-assessment-session':sessionToken},body:JSON.stringify({targetUrl:targetOrigin})});raw.textContent=JSON.stringify(d,null,2);state.textContent=d.error?'PARTIAL':'LIVE';await report()}catch(e){raw.textContent='LIVE CHECK FAILED · '+e.message;state.textContent='PARTIAL'}}
async function pollFullAssessment(){
 const deadline=Date.now()+6*60*1000;let transientErrors=0;
 while(Date.now()<deadline){
  await new Promise(r=>setTimeout(r,2500));
  try{
   const w=await jf('/api/assessments/'+assessmentId+'/security-workspace');
   const r=await jf('/api/assessments/'+assessmentId+'/report',{headers:{'x-assessment-session':sessionToken}});
   const fs=r.findings||[];renderFindings(fs);const evidenceRows=await loadExecutionEvidence();transientErrors=0;
   const status=String(w.assessment?.status||'RUNNING');
   gate.textContent=status+' · '+assessmentId+' · '+targetOrigin+' · '+Number(w.offensive?.findings||0)+' finding(s) · '+Number(w.offensive?.evidenceRecords||0)+' evidence record(s) · '+evidenceRows.length+' evidence record(s) rendered';
   state.textContent=status==='RUNNING'?'SCANNING':status;
   if(['COMPLETED','PARTIAL','FAILED'].includes(status)){await loadExecutionEvidence();await loadSecurityAssets();return status}
  }catch(e){transientErrors++;raw.textContent='Assessment is still running. Progress refresh temporarily failed ('+transientErrors+'). The server-side scan continues independently.\n\n'+e.message}
 }
 state.textContent='PARTIAL';gate.textContent='ASSESSMENT STILL RUNNING · '+assessmentId+' · browser polling window ended; use Refresh Evidence to continue monitoring.';return 'RUNNING'
}
async function scan(){
 if(!assessmentId||!sessionToken)return raw.textContent='Authorize the target first inside Offensive Security.';
 if(tool.value==='quick')return quickScan();
 try{
  const full=tool.value==='all';
  raw.textContent=full?'SUBMITTING FULL URL ASSESSMENT…':'Executing deep real '+tool.value+' scan…';state.textContent='SCANNING';
  if(full){const box=document.getElementById('urlAnalysisSummary');if(box)box.innerHTML='<div class="capability-card"><b>STARTING</b><small>Submitting authorized assessment</small></div>';gate.textContent='STARTING · '+assessmentId+' · '+targetOrigin}
  const d=await jf('/api/scans/run',{method:'POST',headers:{'Content-Type':'application/json','x-assessment-session':sessionToken},body:JSON.stringify({targetUrl:targetOrigin,tool:tool.value})});
  if(full&&d.status==='RUNNING'){gate.textContent='RUNNING · '+assessmentId+' · '+targetOrigin+' · server-side assessment accepted';raw.textContent='ASSESSMENT ACCEPTED\n\nThe server is executing HTTP posture, Nuclei, bounded Nmap discovery, ZAP, Wapiti and SQLmap. This page now polls persisted PostgreSQL evidence; no long proxy request is held open.';await pollFullAssessment();return}
  raw.textContent=JSON.stringify(d,null,2);state.textContent=full?(d.status==='COMPLETED'?'SCANNED':d.status==='PARTIAL'?'PARTIAL':'FAILED'):(d.exitCode===0?'SCANNED':'FAILED');await report()
 }catch(e){raw.textContent='ASSESSMENT START FAILED · '+e.message;state.textContent='FAILED';gate.textContent='ANALYSIS FAILED · '+e.message;try{await report()}catch{}}
}
let lastDocScan=null;async function scanQuickDoc(){const f=quickdoc.files[0];if(!f)return quickdocmsg.textContent='Choose a PDF or Office document first.';const fd=new FormData();fd.append('file',f);quickdocmsg.textContent='Scanning in memory…';try{lastDocScan=await jf('/api/documents/security-scan',{method:'POST',body:fd});quickdocmsg.textContent=lastDocScan.verdict+' · Risk '+lastDocScan.riskScore+'/10 · '+lastDocScan.signals.length+' indicator(s)';raw.textContent=JSON.stringify(lastDocScan,null,2);const sev=lastDocScan.signals.map(x=>({severity:x.severity}));renderFindings(sev)}catch(e){quickdocmsg.textContent='Document scan failed: '+e.message}}
function downloadDocScan(){if(!lastDocScan)return alert('Scan a document first');const b=new Blob([JSON.stringify(lastDocScan,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='aegis-document-security-scan.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function charts(fs){const cv=document.getElementById('pie'),cx=cv.getContext('2d'),w=cv.width=cv.clientWidth*devicePixelRatio,h=cv.height=cv.clientHeight*devicePixelRatio;cx.scale(devicePixelRatio,devicePixelRatio);const W=cv.clientWidth,H=cv.clientHeight,keys=['CRITICAL','HIGH','MEDIUM','LOW','INFO'],cols=['#ef4444','#f97316','#eab308','#22d3ee','#64748b'],vals=keys.map(k=>fs.filter(f=>f.severity===k).length),total=Math.max(1,vals.reduce((a,b)=>a+b,0));cx.clearRect(0,0,W,H);let a=-Math.PI/2;vals.forEach((v,i)=>{const z=v/total*Math.PI*2;cx.beginPath();cx.moveTo(W*.3,H*.5);cx.arc(W*.3,H*.5,Math.min(W,H)*.28,a,a+z);cx.fillStyle=cols[i];cx.fill();a+=z});cx.fillStyle='#dbeafe';cx.font='14px system-ui';keys.forEach((k,i)=>cx.fillText(k+' '+vals[i],W*.62,48+i*28));const b=document.getElementById('bars'),bx=b.getContext('2d'),bw=b.width=b.clientWidth*devicePixelRatio,bh=b.height=b.clientHeight*devicePixelRatio;bx.scale(devicePixelRatio,devicePixelRatio);const BW=b.clientWidth,BH=b.clientHeight,m=Math.max(1,...vals);vals.forEach((v,i)=>{const x=30+i*(BW-50)/5,hh=v/m*(BH-70);bx.fillStyle=cols[i];bx.fillRect(x,BH-35-hh,(BW-80)/6,hh);bx.fillStyle='#cbd5e1';bx.font='11px system-ui';bx.fillText(String(v),x,BH-42-hh);bx.fillText(keys[i].slice(0,4),x,BH-15)})}
function renderFindings(fs){const c={CRITICAL:0,HIGH:0,MEDIUM:0,LOW:0,INFO:0};fs.forEach(f=>c[f.severity]=(c[f.severity]||0)+1);Object.keys(c).forEach(k=>document.getElementById(k).textContent=c[k]);count.textContent=fs.length;const scores=fs.filter(f=>f.cvss!==null&&f.cvss!==undefined&&f.cvss!=='').map(f=>Number(f.cvss)).filter(Number.isFinite),highest=scores.length?Math.max(...scores):0,score=Math.round(highest*10);risk.textContent=(highest?highest.toFixed(1):'0.0')+' CVSS';riskbar.style.width=score+'%';findings.textContent=fs.length?JSON.stringify(fs,null,2):'No normalized vulnerability finding has been produced yet. This is not proof that the target is vulnerability-free; check execution evidence and coverage status.';const box=document.getElementById('urlAnalysisSummary');if(box){const sqli=fs.filter(f=>f.source==='sqlmap'||/sql injection|sqli/i.test(String(f.title||''))),web=fs.filter(f=>['zap','wapiti','nuclei','http'].includes(f.source)),critical=c.CRITICAL+c.HIGH;box.innerHTML='<div class="capability-card"><b>'+fs.length+'</b><small>Evidence-backed findings</small></div><div class="capability-card"><b>'+(highest?highest.toFixed(1):'N/A')+'</b><small>Highest observed CVSS</small></div><div class="capability-card"><b>'+critical+'</b><small>Critical / High findings</small></div><div class="capability-card"><b>'+web.length+'</b><small>Web / exposure findings</small></div><div class="capability-card"><b>'+sqli.length+'</b><small>SQL injection findings</small></div><div class="capability-card"><b>NOT ESTABLISHED</b><small>Live data breach / theft evidence</small></div><div class="capability-card"><b>NOT ESTABLISHED</b><small>Ransomware incident evidence</small></div><div class="capability-card"><b>NOT ESTABLISHED</b><small>Certificate theft evidence</small></div>'}charts(fs)}
function evidenceView(e){
 const meta=e&&e.metadata||{},prov=meta.provenance||{};
 const clip=v=>{const s=String(v||'').trim();return s.length>1800?s.slice(0,1800)+'\n… [truncated in workspace; full record remains stored]':s};
 return {
  engine:String(e.source||'unknown').toUpperCase(),
  status:e.exitCode===0?'SUCCEEDED':e.exitCode===null||e.exitCode===undefined?'RECORDED':'FAILED / NON-ZERO',
  exitCode:e.exitCode??null,
  collectedAt:e.createdAt||null,
  sha256:e.sha256||null,
  target:meta.target||prov.sourceRef||null,
  mode:meta.mode||prov.verificationMethod||null,
  trust:meta.evidenceTrust||null,
  provenanceFingerprint:meta.provenanceFingerprint||null,
  limitations:meta.provenanceLimitations||prov.limitations||[],
  stdout:clip(e.stdout),
  stderr:clip(e.stderr)
 };
}
async function loadExecutionEvidence(){
 if(!assessmentId){raw.textContent='Authorize an assessment to load execution evidence.';return []}
 try{
  const ev=await jf('/api/assessments/'+assessmentId+'/evidence');
  const rows=Array.isArray(ev)?ev:[];
  raw.textContent=rows.length?JSON.stringify(rows.map(evidenceView),null,2):'No persisted scanner evidence yet. This does not mean the target is vulnerability-free.';
  return rows
 }catch(e){raw.textContent='Execution evidence temporarily unavailable. Persisted findings are unchanged.\n\n'+e.message;return []}
}
