function renderDefensiveAnalysis(d){const plan=document.getElementById('defensivePlan');if(!plan)return;const p=d.posture||{},actions=d.actions||[],life=d.lifecycle||[],hard=d.detectionAndHardening||{},limits=d.limitations||[];plan.innerHTML='<div class="defense-posture-strip"><div><span>OPEN FINDINGS</span><b>'+Number(p.openFindings||0)+'</b></div><div><span>CRITICAL</span><b>'+Number(p.critical||0)+'</b></div><div><span>HIGH</span><b>'+Number(p.high||0)+'</b></div><div><span>EVIDENCE</span><b>'+Number(p.evidenceRecords||0)+'</b></div></div><div class="defense-lifecycle">'+life.map((x,i)=>'<span>'+(i+1)+' · '+esc(x)+'</span>').join('')+'</div><div class="defense-evidence-line"><strong>Evidence sources</strong><span>'+esc((p.evidenceSources||[]).join(', ')||'No persisted source evidence')+'</span></div><div class="defense-section-title">Prioritized remediation & targeted retest</div><div class="defense-remediation-list">'+(actions.length?actions.map(defensiveActionCard).join(''):'<div class="defense-empty">No open evidence-backed findings require a remediation action. This is not proof that untested surfaces are secure.</div>')+'</div><div class="defense-section-title">Detection & hardening guidance</div><div class="defense-guidance"><div><strong>Observed telemetry</strong><span>'+esc((hard.telemetryAvailable||[]).join(', ')||'No supported telemetry source observed')+'</span></div>'+(hard.recommendations||[]).map(x=>'<div><strong>HARDEN</strong><span>'+esc(x)+'</span></div>').join('')+'</div><div class="defense-limitations"><strong>Assurance boundary</strong>'+limits.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div>'}
