function selectFramework(id,name){selectedFramework=id;fwTitle.textContent=name+' · Evidence Workspace';fwAssessment.textContent='Framework selected. Click Assess Against Framework to run deterministic evidence-to-control mapping.';} async function assessSelectedFramework(){if(!assessmentId)return fwAssessment.textContent='Authorize and assess a URL first.';if(!selectedFramework)return fwAssessment.textContent='Select a framework first.';fwAssessment.textContent='Running backend framework assessment…';try{const d=await jf('/api/assessments/'+assessmentId+'/framework-assessment/'+selectedFramework);fwAssessment.textContent=JSON.stringify(d,null,2)}catch(e){fwAssessment.textContent=e.message}}
function downloadFramework(){if(!assessmentId)return alert('Authorize an assessment first');if(!selectedFramework)return alert('Select a framework first');pendingExport={framework:selectedFramework,format:fwFormat.value};rpw.value='';rotp.value='';rmsg.textContent='';reauth.classList.remove('hidden')}
let pendingExport=null;function downloadKind(kind){if(!assessmentId)return alert('Authorize an assessment first');pendingExport={kind,format:document.getElementById('fmt-'+kind).value};rpw.value='';rotp.value='';rmsg.textContent='';reauth.classList.remove('hidden');rpw.focus()}function cancelExport(){pendingExport=null;reauth.classList.add('hidden')}async function confirmExport(){if(!pendingExport)return;const {kind,framework,format}=pendingExport;const password=rpw.value,code=rotp.value.trim();if(!password||!/^[0-9]{6}$/.test(code)){rmsg.textContent='Enter your current AegisGRC account password and the current 6-digit authenticator code.';return}const path=framework?('/api/assessments/'+encodeURIComponent(assessmentId)+'/framework-report/'+encodeURIComponent(framework)+'/'+encodeURIComponent(format)):('/api/assessments/'+encodeURIComponent(assessmentId)+'/export/'+encodeURIComponent(kind)+'/'+encodeURIComponent(format));const btn=reauth.querySelector('button');if(btn)btn.disabled=true;rmsg.textContent='Verifying account and preparing report…';try{const r=await fetch(path,{credentials:'same-origin',headers:{'x-assessment-session':sessionToken||'','x-report-password':password,'x-report-totp':code,'Accept':'application/octet-stream'}});if(!r.ok){let d={};try{d=await r.json()}catch{};const reason=d.code||d.reason||'';if(r.status===401&&/SESSION_MISSING|USER_SESSION_MISSING/.test(reason+' '+(d.error||'')))throw Error('Your login session has expired. Sign in again, then retry the export.');if(r.status===401&&/PASSWORD_INVALID/.test(reason+' '+(d.error||'')))throw Error('The account password is incorrect. Use the password for your currently signed-in AegisGRC account, not your computer or email password.');if(r.status===401&&/TOTP_INVALID/.test(reason+' '+(d.error||'')))throw Error('Authenticator code invalid or expired. Enter the newest 6-digit code and check device time.');throw Error(d.error||'Report download failed (HTTP '+r.status+').')}const b=await r.blob();if(!b.size)throw Error('The server returned an empty report.');const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='aegis-'+String(framework||kind).toLowerCase()+'-'+assessmentId+'.'+format;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);cancelExport()}catch(e){rmsg.textContent=e.message||'Unable to download report. Please retry.'}finally{rpw.value='';rotp.value='';if(btn)btn.disabled=false}}

async function submitCurrentForReview(){if(!assessmentId)return reviewMsg.textContent='Authorize an assessment first.';const fw=reviewFramework.value||selectedFramework;if(!fw)return reviewMsg.textContent='Select a framework.';reviewMsg.textContent='Submitting…';try{const d=await jf('/api/assessments/'+assessmentId+'/grc-reviews/'+encodeURIComponent(fw)+'/submit',{method:'POST'});reviewMsg.textContent='Submitted for independent GRC review · '+d.review.status;await loadReviewCenter()}catch(e){reviewMsg.textContent=e.message}}
function reviewCounts(rs){const n=x=>rs.filter(r=>r.status===x).length;rsSubmitted.textContent=n('SUBMITTED');rsReview.textContent=n('IN_REVIEW');rsChanges.textContent=n('CHANGES_REQUESTED');rsApproved.textContent=n('APPROVED');rsRejected.textContent=n('REJECTED')}
function reviewCard(r,canDecide){const id=esc(r.id),status=esc(r.status),notes=esc(r.consultant_notes||'');return '<div class="reviewitem"><div class="reviewtop"><div><b>'+esc(r.framework)+' · '+esc(r.assessment_id)+'</b><div class="muted">Submitted '+new Date(r.submitted_at).toLocaleString()+(r.reviewed_at?' · Reviewed '+new Date(r.reviewed_at).toLocaleString():'')+'</div></div><span class="reviewbadge '+status+'">'+status.replaceAll('_',' ')+'</span></div>'+(notes?'<p><b>Consultant notes:</b> '+notes+'</p>':'')+(r.status==='APPROVED'?'<div class="approvalSeal">✓ GRC TEAM APPROVED<br><small>Reviewed '+(r.approved_at?new Date(r.approved_at).toLocaleString():'and recorded')+'</small></div>':'')+(canDecide?'<textarea id="notes-'+id+'" placeholder="Consultant review notes / evidence gaps / required actions"></textarea><div class="row"><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="IN_REVIEW">Start Review</button><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="CHANGES_REQUESTED">Request Changes</button><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="REJECTED">Reject</button><button class="btn" data-action="decideReview" data-id="'+esc(id)+'" data-status="APPROVED">Approve</button></div>':'<p class="muted">Decision controls are available only to configured GRC reviewers.</p>')+'</div>'}
async function loadReviewCenter(){if(!assessmentId){reviewQueue.innerHTML='<p class="muted">Authorize an assessment to view or submit its GRC review.</p>';reviewCounts([]);return}let own=[];try{const d=await jf('/api/assessments/'+assessmentId+'/grc-reviews');own=d.reviews||[]}catch(e){reviewQueue.textContent=e.message;return}reviewCounts(own);try{const q=await jf('/api/grc-review-queue');reviewQueue.innerHTML=(q.reviews||[]).length?q.reviews.map(r=>reviewCard(r,true)).join(''):'<p class="muted">No reports are waiting for review.</p>';reviewCounts(q.reviews||[])}catch(e){reviewQueue.innerHTML=own.length?own.map(r=>reviewCard(r,false)).join(''):'<p class="muted">No review submitted for this assessment yet.</p>'}}
async function decideReview(id,status){const el=document.getElementById('notes-'+id),notes=el?el.value:'';if((status==='CHANGES_REQUESTED'||status==='REJECTED')&&!notes.trim())return alert('Consultant notes are required for this decision.');try{await jf('/api/grc-reviews/'+id+'/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,notes})});reviewMsg.textContent='Review decision recorded: '+status.replaceAll('_',' ');await loadReviewCenter()}catch(e){reviewMsg.textContent=e.message}}

function auditTraceCard(x){const latest=(x.reviews||[]).at(-1),issue=x.issue,risks=x.risks||[],capas=x.capa||[];return '<div class="reviewitem"><div class="reviewtop"><div><b>'+esc(x.severity||'INFO')+' · '+esc(x.title||x.findingId)+'</b><div class="muted">'+esc(x.source||'unknown')+' · '+esc(x.findingId)+'</div></div><span class="reviewbadge '+esc(latest?.decision||'SUBMITTED')+'">'+esc(latest?.decision||'UNREVIEWED')+'</span></div><p><b>Evidence SHA-256:</b> <span class="u-break-all">'+esc(x.evidenceHash||'Not linked')+'</span></p><p><b>Issue:</b> '+esc(issue?.issue_key||'Not promoted')+(issue?' · '+esc(issue.status)+' · '+esc(issue.priority):'')+'</p><p><b>Enterprise risk:</b> '+(risks.length?risks.map(r=>esc(r.risk_key)+' · '+esc(r.inherent_rating||r.status)).join(' | '):'Not linked')+'</p><p><b>CAPA / retest:</b> '+(capas.length?capas.map(c=>esc(c.capa_key)+' · '+esc(c.status)+(c.retest_run_id?' · retest '+esc(c.retest_run_id):'')).join(' | '):'Not linked')+'</p></div>'}
function renderBreachImpact(rows){if(!rows||!rows.length)return '<p class="muted">No evidence-derived breach-impact decisions are recorded for this assessment.</p>';return '<div class="u-overflow-auto"><table class="u-data-table"><thead><tr><th class="u-th-plain">Status</th><th class="u-th-plain">Impact</th><th class="u-th-plain">Asset</th><th class="u-th-plain">Evidence</th><th class="u-th-plain">Review</th><th class="u-th-plain">Fingerprint</th></tr></thead><tbody>'+rows.map(x=>'<tr><td class="u-td-top">'+esc(grcEmpty(x.status))+'</td><td class="u-td-top">'+esc(grcEmpty(x.impact_band))+' · '+Number(x.impact_score||0)+'</td><td class="u-td-top">'+esc(grcEmpty(x.asset_id))+'</td><td class="u-td-top">'+(Array.isArray(x.evidence)?x.evidence.length:0)+'</td><td class="u-td-top">'+(x.requires_human_review?'REQUIRED':'Not triggered')+'</td><td class="u-td-top"><code>'+esc(String(x.fingerprint||'').slice(0,16))+'…</code></td></tr>').join('')+'</tbody></table></div>'}
async function loadAuditTrace(){if(!assessmentId){auditTraceMsg.textContent='Authorize an assessment first.';auditTraceRows.innerHTML='<p class="muted">No assessment selected.</p>';return}auditTraceMsg.textContent='Loading authenticated trace…';try{const d=await jf('/api/grc/assessments/'+assessmentId+'/traceability');const s=d.summary||{},stats=[['evidence','Evidence'],['findings','Findings'],['confirmed','Confirmed'],['issues','Issues'],['capa','CAPA'],['breachAssessmentsRequiringReview','Breach Review']];auditTraceStats.innerHTML=stats.map(([k,n])=>'<div class="reviewstat"><b>'+Number(s[k]||0)+'</b>'+n+'</div>').join('');auditTraceRows.innerHTML=(d.chains||[]).length?d.chains.map(auditTraceCard).join(''):'<p class="muted">No findings are recorded for this assessment.</p>';breachImpactRows.innerHTML=renderBreachImpact(d.breachImpactAssessments||[]);auditTraceMsg.textContent=d.assuranceBoundary||'Trace loaded.'}catch(e){auditTraceMsg.textContent=e.message;auditTraceRows.textContent='Unable to load traceability.'}}
async function downloadAuditPackage(format){if(!assessmentId)return alert('Authorize an assessment first');try{const q=await jf('/api/assessments/'+assessmentId+'/grc-reviews');const approved=(q.reviews||[]).filter(x=>x.status==='APPROVED').sort((a,b)=>new Date(b.approved_at)-new Date(a.approved_at))[0];if(!approved)throw new Error('Independent GRC approval is required before authenticated audit export. Submit the assessment in GRC Consultant Review Center first.');const v=await jf('/api/assessments/'+assessmentId+'/grc-reviews/'+approved.id+'/verify');if(!v.valid)throw new Error(v.snapshotCurrent===false?'Approved report is stale because governed assessment data changed. Resubmit it for review.':'GRC approval signature could not be verified.');const r=await fetch('/api/grc/assessments/'+assessmentId+'/audit-package.'+format+'?reviewId='+encodeURIComponent(approved.id),{credentials:'same-origin'});if(!r.ok){let d={};try{d=await r.json()}catch{};throw new Error(d.error||'Audit export failed')}const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='AegisGRC-Authenticated-Audit-'+assessmentId+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);auditTraceMsg.textContent='Authenticated audit package generated from approved snapshot '+approved.snapshot_digest+'.'}catch(e){auditTraceMsg.textContent=e.message}}

async function uploadDocs(){if(!assessmentId)return alert('Authorize an assessment first');if(targetOrigin&&docs.files.length){const combine=confirm('A URL is already active.\n\nOK: combine URL and document evidence in the same assessment/report.\nCancel: keep them separate.');if(!combine){docs.value='';docmsg.textContent='Not combined. Start a separate document assessment if you want document-only scope.';return}}const fd=new FormData();[...docs.files].forEach(f=>fd.append('files',f));docmsg.textContent='Uploading…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents',{method:'POST',body:fd});docmsg.textContent=d.documents.length+' file(s) securely stored as assessment evidence';docs.value='';loadDocs()}catch(e){docmsg.textContent=e.message}}
async function loadDocs(){if(!assessmentId)return;try{const ds=await jf('/api/assessments/'+assessmentId+'/documents');doclist.innerHTML=ds.length?ds.map(d=>'<div class="docrow"><div><b>'+esc(d.filename)+'</b><br><small class="muted">Verified assessment evidence</small></div><div>'+Math.ceil(d.size/1024)+' KB</div><div>'+new Date(d.createdAt).toLocaleString()+'</div><div><button class="btn" data-action="securityAssessDoc" data-id="'+esc(d.id)+'">Security Assess</button> <button class="btn alt" data-action="getDoc" data-id="'+esc(d.id)+'">Download</button> <button class="btn alt" data-action="delDoc" data-id="'+esc(d.id)+'">Delete</button></div></div>').join(''):'<p class="muted">No evidence documents stored.</p>'}catch(e){doclist.textContent=e.message}}
async function securityAssessDoc(id){docmsg.textContent='Running evidence-backed document security assessment…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents/'+id+'/security-assess',{method:'POST'});docmsg.textContent='Complete: '+(d.defensive?.findings||[]).length+' evidence-backed finding(s)';raw.textContent=JSON.stringify(d.offensive,null,2);const plan=document.getElementById('defensivePlan');if(plan)plan.textContent=JSON.stringify({defensive:d.defensive,remediation:d.remediation,limitations:d.limitations},null,2);await report();await loadDefensiveAnalysis()}catch(e){docmsg.textContent=e.message}}
